output_text:
[
  {
    "id": "no_cart_in_single_file_shelf_aisles",
    "text": "Carts are not allowed in the one-cell-wide shelf aisles where shelves flank both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileHorizontal": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelvesOnBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "upperSingleFileShelfAisle": {
          "and": [
            "singleFileHorizontal",
            "shelvesOnBothSides"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "upperSingleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "do_not_enter_single_file_aisle_with_cart",
    "text": "A shopper must not push a cart from a wider aisle into a one-cell-wide shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileHorizontal": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelvesOnBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "upperSingleFileShelfAisle": {
          "and": [
            "singleFileHorizontal",
            "shelvesOnBothSides"
          ]
        }
      },
      "events": {
        "enterSingleFileAisleWithCart": {
          "pre": {
            "and": [
              "hasCart",
              {
                "not": "upperSingleFileShelfAisle"
              },
              "MOVE"
            ]
          },
          "post": "upperSingleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileAisleWithCart"
    }
  },
  {
    "id": "cartless_only_for_narrow_aisle_excursions",
    "text": "After taking a cart, a shopper may move without it only in the cart bay, at an upper-aisle mouth, or inside the associated one-cell-wide shelf aisle.",
    "abstraction": {
      "state_properties": {
        "cartBayArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "singleFileHorizontal": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelvesOnBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "upperSingleFileShelfAisle": {
          "and": [
            "singleFileHorizontal",
            "shelvesOnBothSides"
          ]
        },
        "upperAisleMouth": {
          "and": [
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            },
            {
              "ge": [
                "freeWidthH",
                12
              ]
            }
          ]
        },
        "cartlessPermittedZone": {
          "or": [
            "cartBayArea",
            "upperAisleMouth",
            "upperSingleFileShelfAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "cartlessPermittedZone"
          }
        ]
      }
    }
  },
  {
    "id": "reclaim_cart_after_parking",
    "text": "Whenever a shopper parks or releases a cart, they must later reclaim a cart before finishing the trip.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "reclaimCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "reclaimCart"
    }
  },
  {
    "id": "narrow_shelf_interaction_must_be_cartless",
    "text": "Shelf interactions inside the one-cell-wide upper aisles must be performed without the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileHorizontal": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelvesOnBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "upperSingleFileShelfAisle": {
          "and": [
            "singleFileHorizontal",
            "shelvesOnBothSides"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "upperSingleFileShelfAisle",
          "hasCart",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "ordinary_shelf_interaction_requires_cart",
    "text": "Shelf interactions outside the one-cell-wide upper aisles should be done with the cart present.",
    "abstraction": {
      "state_properties": {
        "singleFileHorizontal": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelvesOnBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "upperSingleFileShelfAisle": {
          "and": [
            "singleFileHorizontal",
            "shelvesOnBothSides"
          ]
        },
        "ordinaryShelfServiceLocation": {
          "and": [
            "adjShelf",
            {
              "not": "upperSingleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "ordinaryShelfServiceLocation",
          {
            "not": "hasCart"
          },
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "cart_handling_only_at_bays_or_aisle_mouths",
    "text": "Cart pickup, parking, and reclamation should occur only at the entrance cart bay or at the mouths of the upper single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "entranceCartBay": {
          "and": [
            "at(1,7)",
            {
              "ge": [
                "freeWidthH",
                12
              ]
            }
          ]
        },
        "upperAisleMouth": {
          "and": [
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            },
            {
              "ge": [
                "freeWidthH",
                12
              ]
            }
          ]
        },
        "cartHandlingZone": {
          "or": [
            "entranceCartBay",
            "upperAisleMouth"
          ]
        }
      },
      "events": {
        "detachCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "attachCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "or": [
              "detachCart",
              "attachCart"
            ]
          },
          {
            "not": "cartHandlingZone"
          }
        ]
      }
    }
  },
  {
    "id": "entering_narrow_aisle_obliges_shelf_service",
    "text": "If a shopper enters a one-cell-wide upper shelf aisle on foot, they are expected to perform a shelf interaction there before leaving the excursion unresolved.",
    "abstraction": {
      "state_properties": {
        "singleFileHorizontal": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelvesOnBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "upperSingleFileShelfAisle": {
          "and": [
            "singleFileHorizontal",
            "shelvesOnBothSides"
          ]
        },
        "cartlessNarrowShelfInteraction": {
          "and": [
            "upperSingleFileShelfAisle",
            {
              "not": "hasCart"
            },
            "INTERACT"
          ]
        }
      },
      "events": {
        "enterUpperAisleOnFoot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              {
                "not": "upperSingleFileShelfAisle"
              },
              "MOVE"
            ]
          },
          "post": "upperSingleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterUpperAisleOnFoot",
      "discharge": "cartlessNarrowShelfInteraction"
    }
  }
]
